var PAYDAYS=[10,25];
/* Philippine holidays: regular holidays and special non-working days with fixed or computed dates.
   Chinese New Year and the two Eid holidays change every year and are announced late, so add them to EXTRA_HOLIDAYS when they're declared. */
var EXTRA_HOLIDAYS=[];
var holCache={};
function easter(y){var a=y%19,b=Math.floor(y/100),c=y%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),mo=Math.floor((h+l-7*m+114)/31),da=((h+l-7*m+114)%31)+1;return new Date(y,mo-1,da);}
function holidaysOf(y){
  if(holCache[y])return holCache[y];
  var H={};
  [['01-01','New Year’s Day'],['04-09','Araw ng Kagitingan'],['05-01','Labor Day'],['06-12','Independence Day'],['08-21','Ninoy Aquino Day'],['11-01','All Saints’ Day'],['11-02','All Souls’ Day'],['11-30','Bonifacio Day'],['12-08','Immaculate Conception'],['12-24','Christmas Eve'],['12-25','Christmas Day'],['12-30','Rizal Day'],['12-31','Last Day of the Year']]
    .forEach(function(x){H[y+'-'+x[0]]=x[1];});
  var e=easter(y);H[ymd(addDays(e,-3))]='Maundy Thursday';H[ymd(addDays(e,-2))]='Good Friday';H[ymd(addDays(e,-1))]='Black Saturday';
  var lm=new Date(y,8,0);while(lm.getDay()!==1)lm=addDays(lm,-1);H[ymd(lm)]='National Heroes Day';
  EXTRA_HOLIDAYS.forEach(function(x){if(x[0].slice(0,4)===String(y))H[x[0]]=x[1];});
  return holCache[y]=H;
}
function holidayName(ds){return holidaysOf(+ds.slice(0,4))[ds]||'';}
/* Payday falls on the 10th and 25th; on a weekend or holiday it moves to the working day before */
function paydayDate(y,m,day){
  var d=new Date(y,m,day);
  while(d.getDay()===0||d.getDay()===6||holidayName(ymd(d)))d=addDays(d,-1);
  return d;
}
function isPayday(ds){var y=+ds.slice(0,4),m=+ds.slice(5,7)-1;return PAYDAYS.some(function(p){return ymd(paydayDate(y,m,p))===ds;});}
var LEAVES=[
  {code:'BL',label:'Birthday leave',c:'#e8a0c4',t:'#3f0f28'},
  {code:'VL',label:'Vacation leave',c:'#8fc1f2',t:'#06233f'},
  {code:'SL',label:'Sick leave',c:'#f3c257',t:'#3a2600'}
];
function leaveInfo(code){for(var i=0;i<LEAVES.length;i++){if(LEAVES[i].code===code)return LEAVES[i];}return null;}
function leaveFor(ds){return state.leaves.find(function(l){return l.date===ds;})||null;}
function validLeave(l){return l&&/^\d{4}-\d{2}-\d{2}$/.test(l.date)&&LEAVES.some(function(x){return x.code===l.type;});}
var WARDCATS={
  '9':{label:'9',buildings:['Annex Bldg','Cul de Sac Bldg','Outborn NICU','Urgent Care']},
  '5':{label:'5',buildings:['VLM Building','Main Building']}
};

/* ---------- helpers ---------- */
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function pad(n){return String(n).padStart(2,'0');}
function ymd(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());}
function parseYmd(s){var p=s.split('-').map(Number);return new Date(p[0],p[1]-1,p[2]);}
function addDays(d,n){var x=new Date(d.getFullYear(),d.getMonth(),d.getDate());x.setDate(x.getDate()+n);return x;}
function toMin(t){var p=t.split(':').map(Number);return p[0]*60+p[1];}
function crosses(d){return toMin(d.end)<=toMin(d.start);}
function startDT(d){var x=parseYmd(d.date);x.setMinutes(toMin(d.start));return x;}
function endDT(d){var x=parseYmd(d.date);x.setMinutes(toMin(d.end)+(crosses(d)?1440:0));return x;}
function hours(d){return noTimePost(d.post)?0:(endDT(d)-startDT(d))/3600000;}
function span(ms){var m=Math.max(1,Math.round(ms/60000));var h=Math.floor(m/60),r=m%60;return h?(r?h+'h '+r+'m':h+'h'):r+'m';}
function payTag(ds){return (isPayday(ds)?'<span class="paytag">Pay</span>':'')+(holidayName(ds)?'<span class="holtag" title="'+esc(holidayName(ds))+'">Hol</span>':'');}
function payLine(now){
  var t=new Date(now.getFullYear(),now.getMonth(),now.getDate()),c=null;
  for(var m=0;m<3;m++){PAYDAYS.forEach(function(d){var x=paydayDate(t.getFullYear(),t.getMonth()+m,d);if(x>=t&&(!c||x<c))c=x;});}
  var diff=Math.round((c-t)/86400000);
  var label=DOWS[c.getDay()]+' '+c.getDate()+' '+MONTHS[c.getMonth()].slice(0,3);
  var txt=diff===0?'Payday today':diff===1?'Payday tomorrow · '+label:'Next payday in '+diff+' days · '+label;
  return '<p class="pay'+(diff===0?' now':'')+'">'+esc(txt)+'</p>';
}
function postLabel(d){
  var n=pinfo(d.post).name;
  if(d.post==='Warding'&&d.ward){
    var cov=WARDCATS[d.ward]?WARDCATS[d.ward].buildings.join(', '):d.building;
    n+=' · '+d.ward+(cov?' ('+cov+')':'');
  }
  return n;
}
function noTimePost(post){return !!pinfo(post).noTime;}
function pinfo(post){
  var k=String(post).trim().toLowerCase();
  for(var i=0;i<POSTS.length;i++){var P=POSTS[i];if(P.name.toLowerCase()===k||(P.alt&&P.alt.indexOf(k)>-1))return P;}
  return {name:String(post),short:String(post).trim().slice(0,5),c:'#5f6b76',t:'#ffffff'};
}
function cstyle(post){var p=pinfo(post);return '--c:'+p.c+';--t:'+p.t;}
function matchPost(text){
  var x=String(text).toLowerCase();
  if(/bact|microbio|\bbc\b/.test(x))return 'Bacteriology';
  if(/chem|\bcc\b/.test(x))return 'Clinical chemistry';
  if(/micro|\bcm\b/.test(x))return 'Clinical microscopy';
  if(/\bmbd\b|mass blood|blood donation/.test(x))return 'Mass Blood Donation';
  if(/blood|\bbb\b/.test(x))return 'Blood bank';
  if(/hema|\bhm\b/.test(x))return 'Hematology';
  if(/ward|\bwd\b/.test(x))return 'Warding';
  if(/\ber\b|emergency/.test(x))return 'ER';
  if(/sat(ellite)?/.test(x))return 'Satellite';
  if(/\bopd\b|outpatient/.test(x))return 'Outpatient Department';
  if(/\bob\b|official business/.test(x))return 'Official Business';
  return 'Unknown post';
}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7);}
function fmt(t){
  if(state.settings.h24)return t;
  var p=t.split(':').map(Number),h=p[0],m=p[1],ap=h>=12?'PM':'AM';
  h=h%12||12;return h+':'+pad(m)+' '+ap;
}
function shiftOf(d){
  if(noTimePost(d.post))return null;
  for(var i=0;i<SHIFTS.length;i++){if(SHIFTS[i].start===d.start&&SHIFTS[i].end===d.end)return SHIFTS[i];}
  return null;
}
function shiftByCode(c){for(var i=0;i<SHIFTS.length;i++){if(SHIFTS[i].code===c)return SHIFTS[i];}return null;}
function times(d){return noTimePost(d.post)?'No set time':fmt(d.start)+' – '+fmt(d.end);}
function tshort(t){
  if(state.settings.h24)return t;
  var p=t.split(':').map(Number),h=p[0]%12||12,ap=p[0]>=12?'PM':'AM';
  return h+(p[1]?':'+pad(p[1]):'')+' '+ap;
}
function rowRange(d){
  if(noTimePost(d.post))return 'No set time';
  var sc=shiftOf(d);
  return (sc?'<span class="scode sm">'+esc(sc.code)+'</span>':'')+tshort(d.start)+' – '+tshort(d.end);
}
function range(d){var s=shiftOf(d);return (s?s.code+' · ':'')+times(d);}
function dur(d){return noTimePost(d.post)?'':span(endDT(d)-startDT(d));}
function cmp(a,b){return startDT(a)-startDT(b);}
function offLabel(ds){var l=leaveFor(ds);return l?leaveInfo(l.type).code+' · '+leaveInfo(l.type).label:'RD · Rest day';}
function dayLabel(dateStr,today){
  var d=parseYmd(dateStr),t=parseYmd(today),diff=Math.round((d-t)/86400000);
  if(diff===0)return 'Today';if(diff===1)return 'Tomorrow';if(diff===-1)return 'Yesterday';
  return DOWS[d.getDay()]+' '+d.getDate()+' '+MONTHS[d.getMonth()].slice(0,3);
}

/* ---------- state + storage ---------- */
var state={duties:[],settings:{h24:true,cutoff:'payday'},leaves:[]};
var view='today';
var calMode='grid';
