  h+=brandBar();
  h+='<header class="head withav"><div><h1>'+DOWL[now.getDay()]+'</h1><p>'+now.getDate()+' '+MONTHS[now.getMonth()]+' '+now.getFullYear()+'</p></div>'+
    '<button type="button" class="meav" data-a="avatar" aria-label="Change your avatar">'+myAv+'</button></header>';
  if(syncMode==='device')h+='<p class="sync">Not syncing online. Your roster is saved on this device only.</p>';
