function hourOpts(sel){
  var o='',found=false;
  for(var h=0;h<24;h++){var v=pad(h)+':00';if(v===sel)found=true;o+='<option value="'+v+'"'+(v===sel?' selected':'')+'>'+fmt(v)+'</option>';}
  if(!found&&sel)o='<option value="'+sel+'" selected>'+fmt(sel)+'</option>'+o;
  return o;
}
function leaveDates(){
  var a=val('f-date'),b=val('f-until')||a,out=[];
  if(!a)return out;if(b<a){var t=a;a=b;b=t;}
  for(var x=parseYmd(a),n=0;ymd(x)<=b&&n<62;x=addDays(x,1),n++)out.push(ymd(x));
  return out;
}
