/* Sheet events */
sheet.addEventListener('click',function(e){
  var b=e.target.closest('[data-s]');if(!b)return;
  var a=b.dataset.s;
  if(a==='close')closeSheet();
  else if(a==='save')saveEditor(b.dataset.id);
  else if(a==='del')armed(b,'Tap again to delete',function(){
    state.duties=state.duties.filter(function(x){return x.id!==b.dataset.id;});
    if(save())toast('Deleted');closeSheet();render();});
  else if(a==='avatar')openAvatarPicker();
  else if(a==='myname')openMyName();
  else if(a==='pw')openPassword();
  else if(a==='savepw')savePassword();
  else if(a==='tour'){closeSheet();setTimeout(startTour,250);}
  else if(a==='about'){openSheet('<h2 class="visually-hidden">About LabMates</h2>'+welcomeHTML(true));initWelcome(sheet,true);}
  else if(a==='savename')saveMyName();
  else if(a==='members')openMembers();
  else if(a==='mset')setMemberStatus(b,b.dataset.id,b.dataset.v);
  else if(a==='signout')armed(b,'Tap again to sign out',function(){closeSheet();signOut();});
  else if(a==='cmpp'){var ci=cmpSel.indexOf(b.dataset.v);if(ci>-1)cmpSel.splice(ci,1);else{cmpSel.push(b.dataset.v);cmpQuery='';}drawCompare();}
  else if(a==='cmpf'){cmpFilter=b.dataset.v;drawCompare();}
  else if(a==='avpick'){avPick={k:'i',i:+b.dataset.v};drawAvatarPicker();}
  else if(a==='avsave'){state.settings.avatar={k:'i',i:avPick.i};if(save())toast('Avatar saved');closeSheet();render();}
  else if(a==='mode'){ed.mode=b.dataset.v;document.getElementById('f-err').textContent='';syncEditorUI();}
  else if(a==='pickleave'){ed.leave=b.dataset.v;syncEditorUI();}
  else if(a==='shift'){var s=shiftByCode(b.dataset.v);if(s){ed.custom=false;ed.start=s.start;ed.end=s.end;syncEditorUI();}}
  else if(a==='custom'){ed.custom=true;ed.start=val('f-cs');ed.end=val('f-ce');syncEditorUI();}
  else if(a==='pickpost'){ed.post=b.dataset.v;if(ed.post!=='Warding'){ed.ward='';ed.building='';}syncEditorUI();}
  else if(a==='wardcat'){ed.ward=b.dataset.v;syncEditorUI();}
  else if(a==='setleave'){setLeave(offSheetDate,b.dataset.v);}
  else if(a==='stats')openStats('year');
  else if(a==='statsperiod')openStats(b.dataset.v);
  else if(a==='add')openEditor(null,b.dataset.date);
  else if(a==='import')openImport();
  else if(a==='doimport')doImport();
  else if(a==='export')openExport();
  else if(a==='doexport'){exportMonth(b.dataset.v);closeSheet();}
  else if(a==='backup')openBackup();
  else if(a==='copy'){
    var ta=document.getElementById('bak');ta.select();
    var done=false;
    try{if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(ta.value).then(function(){toast('Copied');},function(){toast('Select the text and copy it');});done=true;}}catch(x){}
    if(!done){try{document.execCommand('copy');toast('Copied');}catch(x){toast('Select the text and copy it');}}
  }
  else if(a==='restore')armed(b,'Tap again to replace',function(){
    var err=document.getElementById('bak-err');
    try{
      var o=JSON.parse(val('bak'));
      if(!o||!Array.isArray(o.duties))throw new Error('x');
      state.duties=o.duties.filter(validDuty).map(function(d){d.id=d.id||uid();d.note=d.note||'';return d;});
      state.leaves=Array.isArray(o.leaves)?o.leaves.filter(validLeave).map(function(l){l.id=l.id||uid();return l;}):[];
      if(o.settings){state.settings.h24=o.settings.h24!==false;state.settings.cutoff=o.settings.cutoff==='half'?'half':'payday';if(validAvatar(o.settings.avatar)){var oa=o.settings.avatar;state.settings.avatar={k:'p',h:oa.h,e:oa.e,m:oa.m,x:oa.x};}}
      if(save())toast('Restored '+state.duties.length+' duties');
      closeSheet();render();
    }catch(x){err.textContent="That text isn't a valid backup.";}
  });
  else if(a==='fmt'){state.settings.h24=b.dataset.v==='24';save();render();openMore();}
  else if(a==='clear')armed(b,'Tap again to erase your roster',function(){
    state.duties=[];state.leaves=[];if(save())toast('Your duties were cleared');closeSheet();render();});
});

