/* ---------- scroll arrows for sideways rows ---------- */
var HS_SEL='.daystrip,.cpeople,.boardwrap';
var reduceMotion=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function hsUpdate(w,el){
  var max=el.scrollWidth-el.clientWidth;
  w.classList.toggle('can-l',el.scrollLeft>4);
  w.classList.toggle('can-r',max>4&&el.scrollLeft<max-4);
}
function enhanceScrollers(root){
  if(!root)return;
  root.querySelectorAll(HS_SEL).forEach(function(el){
    if(el.parentNode&&el.parentNode.classList&&el.parentNode.classList.contains('hs'))return;
    var sl=el.scrollLeft,w=document.createElement('div');w.className='hs';
    el.parentNode.insertBefore(w,el);w.appendChild(el);el.scrollLeft=sl;
    ['l','r'].forEach(function(side){
      var b=document.createElement('button');b.type='button';b.className='hs-btn hs-'+side;
      b.setAttribute('aria-label',side==='l'?'Scroll left':'Scroll right');
      b.innerHTML=side==='l'?ARROW_L:ARROW_R;
      b.addEventListener('click',function(e){e.stopPropagation();el.scrollBy({left:(side==='l'?-1:1)*Math.max(120,el.clientWidth*0.7),behavior:reduceMotion?'auto':'smooth'});});
      w.appendChild(b);
    });
    var tick=function(){hsUpdate(w,el);};
    el.addEventListener('scroll',tick,{passive:true});
    el.querySelectorAll('img').forEach(function(i){i.addEventListener('load',tick);});
    tick();requestAnimationFrame(tick);setTimeout(function(){tick();if(w.classList.contains('can-r')&&!reduceMotion)w.classList.add('nudge');},150);
  });
}
window.addEventListener('resize',function(){document.querySelectorAll('.hs').forEach(function(w){var el=w.querySelector(HS_SEL);if(el)hsUpdate(w,el);});});
new MutationObserver(function(){enhanceScrollers(document.getElementById('main'));}).observe(document.getElementById('main'),{childList:true});
new MutationObserver(function(){enhanceScrollers(document.getElementById('sheet'));}).observe(document.getElementById('sheet'),{childList:true});

