function saveMyName(){
  var v=(document.getElementById('f-name').value||'').trim();
  if(!v){document.getElementById('f-err').textContent='Enter your name.';return;}
  sb.from('profiles').update({display_name:v}).eq('id',myId).then(function(r){
    if(r.error){document.getElementById('f-err').textContent="Couldn't save. Check your connection.";return;}
    if(myProfile)myProfile.display_name=v;
    toast('Name saved');closeSheet();queueTeam();
  });
}
function openPassword(){
  openSheet('<h2>Set or change password</h2><p class="hint" style="margin:-6px 0 4px">Lets you sign in with your email and this password. Google sign-in keeps working too.</p>'+
    '<label for="f-pw">New password</label><input type="password" id="f-pw" minlength="6" autocomplete="new-password">'+
    '<p class="hint">At least 6 characters. Any letters, numbers or symbols.</p><p class="gerr" id="f-err"></p>'+
    '<div class="btnrow" style="margin-top:18px"><button type="button" class="btn" data-s="close">Cancel</button><button type="button" class="btn primary" data-s="savepw">Save</button></div>');
}
function savePassword(){
  var v=document.getElementById('f-pw').value||'';
  if(v.length<6){document.getElementById('f-err').textContent='Use at least 6 characters.';return;}
  sb.auth.updateUser({password:v}).then(function(r){
    if(r.error){document.getElementById('f-err').textContent=authMsg(r.error);return;}
    toast('Password saved');closeSheet();
  });
}
function wayLabel(w){
  var g=/google/.test(w),e=/email/.test(w);
  return g&&e?'Google + password':g?'Google':e?'Password':w;
}
function memberRow(p){
  var who=p.id===myId?' (you)':'',btns='';
  if(p.id!==myId){
    if(p.status==='pending')btns='<button type="button" class="btn" data-s="mset" data-v="rejected" data-id="'+esc(p.id)+'">Decline</button><button type="button" class="btn primary" data-s="mset" data-v="approved" data-id="'+esc(p.id)+'">Approve</button>';
    else if(p.status==='approved')btns='<button type="button" class="btn danger" data-s="mset" data-v="rejected" data-id="'+esc(p.id)+'">Remove</button>';
    else btns='<button type="button" class="btn" data-s="mset" data-v="approved" data-id="'+esc(p.id)+'">Restore</button>';
  }
  var d=new Date(p.created_at);
  return '<div class="mrow"><div class="mname"><b>'+esc(p.display_name||'No name')+who+'</b>'+(p.email?'<small class="memail">'+esc(p.email)+'</small>':'')+'<small>'+(p.is_admin?'Admin · ':'')+(p.sign_in?esc(wayLabel(p.sign_in))+' · ':'')+'Joined '+shortDate(d)+' '+d.getFullYear()+'</small></div>'+btns+'</div>';
}
var memberEmails={},memberWays={};
function openMembers(){
  if(!openMembers.loading&&sb){
    openMembers.loading=true;
    sb.rpc('admin_members').then(function(r){
      openMembers.loading=false;
      if(!r.error&&Array.isArray(r.data)){memberEmails={};memberWays={};r.data.forEach(function(x){memberEmails[x.id]=x.email||'';memberWays[x.id]=x.sign_in||'';});}
      if(scrim.classList.contains('open')&&sheet.querySelector('.mrow'))drawMembers();
    },function(){openMembers.loading=false;});
  }
  drawMembers();
}
function drawMembers(){
  members.forEach(function(p){if(memberEmails[p.id])p.email=memberEmails[p.id];if(memberWays[p.id])p.sign_in=memberWays[p.id];});
  var pend=members.filter(function(p){return p.status==='pending';}),
      appr=members.filter(function(p){return p.status==='approved';}),
      rej=members.filter(function(p){return p.status==='rejected';});
  var h='<h2>Members</h2>';
  h+='<h3 class="sec" style="margin:8px 0 4px">Waiting for approval ('+pend.length+')</h3>'+(pend.length?pend.map(memberRow).join(''):'<p class="hint">No one is waiting.</p>');
  h+='<h3 class="sec" style="margin:20px 0 4px">Members ('+appr.length+')</h3>'+appr.map(memberRow).join('');
  if(rej.length)h+='<h3 class="sec" style="margin:20px 0 4px">Removed or declined ('+rej.length+')</h3>'+rej.map(memberRow).join('');
  h+='<p class="hint" style="margin-top:16px">Check the name, email and sign-in method before you approve someone. A password account can use any email, so only approve people you know. Approved members can see everyone’s duties, leave and notes. Removing someone hides the team from them right away; their account stays so you can restore it.</p>';
  h+='<div class="menu" style="margin-top:16px"><button type="button" class="btn" data-s="close">Close</button></div>';
  openSheet(h);
}
function setMemberStatus(btn,id,status){
  var go=function(){
    btn.disabled=true;
    sb.from('profiles').update({status:status}).eq('id',id).then(function(r){
      if(r.error){toast("Couldn't update. Check your connection.");btn.disabled=false;return;}
      members.forEach(function(p){if(p.id===id)p.status=status;});
      toast(status==='approved'?'Approved':'Removed');
      updateBadge();drawMembers();queueTeam();
    });
  };
  if(status==='rejected')armed(btn,'Tap again',go);else go();
}


